    id: sudokuId(day),
    kind: "puzzle",
    title: "Sudoku",
    hook: `${s.level} \xB7 ${empty} squares to fill.`,
    tag: `Sudoku \xB7 ${s.level}`,
    cta: "Play",
    blocks: [{ type: "sudoku", givens: s.givens, solution: s.solution, level: s.level }],
    status: "open",
